/**
 * Google Calendar Control with Apps Script
 * 이 스크립트는 Google 캘린더에 일정을 추가, 조회, 수정하고 트리거를 설정합니다.
 */

// 1. 다음달 1일 일정 09:00~18:00 근무일정 추가하는 함수
function addWorkSchedule() {
  // 다음달 1일 날짜 계산
  const today = new Date();
  const nextMonth = new Date(today.getFullYear(), today.getMonth() + 1, 1);

  // 시작 시간 설정 (09:00)
  const startTime = new Date(nextMonth);
  startTime.setHours(9, 0, 0);

  // 종료 시간 설정 (18:00)
  const endTime = new Date(nextMonth);
  endTime.setHours(18, 0, 0);

  // 캘린더 이벤트 생성
  const calendar = CalendarApp.getDefaultCalendar(); // 기본 캘린더 사용
  const event = calendar.createEvent(
    '근무일정', // 이벤트 제목
    startTime,  // 시작 시간
    endTime,    // 종료 시간
    {
      description: '정규 근무 시간', // 이벤트 설명
      location: '사무실',           // 이벤트 위치
    }
  );

  Logger.log('일정이 추가되었습니다: ' + event.getId());
  return event.getId(); // 이벤트 ID 반환
}

// 2. 다음달 1일 일정 조회 및 출력하는 함수
function getSchedule() {
  // 다음달 1일 날짜 계산
  const today = new Date();
  const nextMonth = new Date(today.getFullYear(), today.getMonth() + 1, 1);

  // 다음날 0시 0분 0초 계산 (하루 전체 일정을 가져오기 위함)
  const nextDay = new Date(nextMonth);
  nextDay.setDate(nextDay.getDate() + 1);
  nextDay.setHours(0, 0, 0);

  // 캘린더에서 해당 날짜의 이벤트 가져오기
  const calendar = CalendarApp.getDefaultCalendar();
  const events = calendar.getEvents(nextMonth, nextDay);

  // 이벤트 정보 출력
  if (events.length === 0) {
    Logger.log('다음달 1일에 예약된 일정이 없습니다.');
    return '일정 없음';
  } else {
    for (let i = 0; i < events.length; i++) {
      const event = events[i];
      Logger.log('이벤트 #' + (i + 1));
      Logger.log('ID: ' + event.getId());
      Logger.log('제목: ' + event.getTitle());
      Logger.log('설명: ' + event.getDescription());
      Logger.log('위치: ' + event.getLocation());
      Logger.log('시작 시간: ' + event.getStartTime());
      Logger.log('종료 시간: ' + event.getEndTime());
      Logger.log('-----------------------------------');
    }
    return events; // 이벤트 배열 반환
  }
}

// 3. 다음달 1일 일정 09:00~18:00 -> 08:00~17:00 로 변경하는 함수
function updateSchedule() {
  // 다음달 1일 날짜 계산
  const today = new Date();
  const nextMonth = new Date(today.getFullYear(), today.getMonth() + 1, 1);

  // 다음날 0시 0분 0초 계산
  const nextDay = new Date(nextMonth);
  nextDay.setDate(nextDay.getDate() + 1);
  nextDay.setHours(0, 0, 0);

  // 캘린더에서 해당 날짜의 이벤트 가져오기
  const calendar = CalendarApp.getDefaultCalendar();
  const events = calendar.getEvents(nextMonth, nextDay);

  // "근무일정" 제목을 가진, 9시에 시작하는 이벤트 찾기
  for (let i = 0; i < events.length; i++) {
    const event = events[i];
    const startTime = event.getStartTime();

    if (event.getTitle() === '근무일정' && startTime.getHours() === 9) {
      // 새로운 시작/종료 시간 설정
      const newStartTime = new Date(startTime);
      newStartTime.setHours(8, 0, 0); // 08:00

      const newEndTime = new Date(event.getEndTime());
      newEndTime.setHours(17, 0, 0); // 17:00

      // 이벤트 업데이트
      event.setTime(newStartTime, newEndTime);
      Logger.log('일정이 업데이트되었습니다. ID: ' + event.getId());
      Logger.log('새 시작 시간: ' + newStartTime);
      Logger.log('새 종료 시간: ' + newEndTime);

      return '업데이트 성공';
    }
  }

  Logger.log('업데이트할 근무일정을 찾을 수 없습니다.');
  return '업데이트 실패';
}

/**
 * 다음달 1일의 "근무일정" 제목을 가진 일정만 삭제하는 함수
 */
function deleteWorkSchedule() {
  // 다음달 1일 날짜 계산
  const today = new Date();
  const nextMonth = new Date(today.getFullYear(), today.getMonth() + 1, 1);

  // 다음날 0시 0분 0초 계산 (하루 전체 일정을 가져오기 위함)
  const nextDay = new Date(nextMonth);
  nextDay.setDate(nextDay.getDate() + 1);
  nextDay.setHours(0, 0, 0);

  // 캘린더에서 해당 날짜의 이벤트 가져오기
  const calendar = CalendarApp.getDefaultCalendar();
  const events = calendar.getEvents(nextMonth, nextDay);

  let deletedCount = 0;

  // "근무일정" 제목을 가진 이벤트 찾기 및 삭제
  for (let i = 0; i < events.length; i++) {
    const event = events[i];

    if (event.getTitle() === '근무일정') {
      // 삭제 전 정보 로깅
      Logger.log('삭제할 일정 정보:');
      Logger.log('- 제목: ' + event.getTitle());
      Logger.log('- 시작 시간: ' + event.getStartTime());
      Logger.log('- 종료 시간: ' + event.getEndTime());

      // 이벤트 삭제
      event.deleteEvent();
      deletedCount++;
    }
  }

  // 결과 출력
  if (deletedCount === 0) {
    Logger.log('다음달 1일에 "근무일정" 제목의 일정이 없습니다.');
  } else {
    Logger.log('총 ' + deletedCount + '개의 "근무일정" 일정이 삭제되었습니다.');
  }

  return deletedCount;
}

// 함수 실행
function main() {
  deleteWorkSchedule();
}

/**
 * 테스트용: 1분마다 다음달 1일에 "근무일정_트리거" 일정을 추가하는 코드
 * 주의: 테스트 완료 후에는 수동으로 트리거를 삭제해야 합니다.
 */

// 트리거로 1분마다 실행될 함수 - 다음달 1일에 근무일정 추가
function addWorkSchedule() {
  // 다음달 1일 날짜 계산
  const today = new Date();
  const nextMonth = new Date(today.getFullYear(), today.getMonth() + 1, 1);

  // 시작 시간(09:00)과 종료 시간(18:00) 설정
  const startTime = new Date(nextMonth);
  startTime.setHours(9, 0, 0);

  const endTime = new Date(nextMonth);
  endTime.setHours(18, 0, 0);

  // 캘린더에서 해당 날짜에 이미 '근무일정_트리거' 일정이 있는지 확인
  const calendar = CalendarApp.getDefaultCalendar();
  const events = calendar.getEventsForDay(nextMonth);

  // 이미 존재하는 '근무일정_트리거' 일정이 있는지 확인
  let existingEventCount = 0;
  for (let i = 0; i < events.length; i++) {
    if (events[i].getTitle() === '근무일정_트리거') {
      existingEventCount++;
    }
  }

  // 테스트 목적으로 기존 일정 개수 로깅
  Logger.log('현재 존재하는 근무일정_트리거 일정 수: ' + existingEventCount);

  // 일정 추가 (테스트 목적이므로 매번 추가)
  const newEvent = calendar.createEvent(
    '근무일정_트리거 #' + (existingEventCount + 1),  // 번호 추가하여 구분
    startTime,                 // 시작 시간 (09:00)
    endTime,                   // 종료 시간 (18:00)
    {description: '트리거 테스트에 의해 생성된 일정: ' + new Date()}
  );

  Logger.log('근무일정_트리거 일정이 추가되었습니다: ' + new Date());

  // 테스트 로그를 위해 일정 ID 기록
  Logger.log('생성된 일정 ID: ' + newEvent.getId());
}

// 1분마다 실행되는 트리거 설정 (테스트용)
function createTrigger() {
  // 새 트리거 추가 (1분마다 실행)
  ScriptApp.newTrigger('addWorkSchedule')
    .timeBased()
    .everyMinutes(1)
    .create();

  Logger.log('1분마다 실행되는 트리거가 설정되었습니다.');
  Logger.log('주의: 테스트 완료 후에는 트리거 탭에서 수동으로 삭제해야 합니다.');
}

// 실행 함수
function main() {
  createTrigger();
  // 트리거 확인을 위해 한 번 실행
  addWorkSchedule();
}
